INSERT INTO claims.claims_837_wide
SELECT
  format('WC%s', lpad(g::text, 7, '0')),  -- claim_id
  (ARRAY['professional', 'institutional'])[1 + (g * 1 + 0) % 2],  -- claim_type
  CASE WHEN g % 20 = 0 THEN '7' WHEN g % 41 = 0 THEN '8' ELSE '1' END,  -- claim_frequency_code
  format('PCN%s', lpad(((g * 13) % 100000)::text, 6, '0')),  -- patient_control_number
  DATE '2025-01-01' + ((g * 11) % 540),  -- statement_from_date
  DATE '2025-01-01' + ((g * 11) % 540) + (g % 3),  -- statement_to_date
  DATE '2025-01-01' + ((g * 11) % 540) + 5,  -- received_date
  CASE WHEN g % 37 = 0 THEN NULL ELSE DATE '2025-01-01' + ((g * 11) % 540) + 19 END,  -- adjudication_date
  CASE WHEN g % 50 = 0 THEN 'reversed' WHEN g % 16 = 0 THEN 'denied' ELSE 'paid' END,  -- claim_status
  round((8000 + (g * 5300) % 220000)::numeric / 100, 2),  -- total_claim_charge
  (ARRAY['11', '21', '22', '23', '81'])[1 + (g * 7 + 0) % 5],  -- place_of_service
  CASE WHEN g % 2 = 0 THEN (ARRAY['111', '131', '137', '851'])[1 + (g * 3 + 0) % 4] END,  -- bill_type_code
