  (ARRAY['100 MAIN ST', '42 OAK AVE', '7 ELM CT', '1600 BIRCH BLVD', '250 CEDAR LN', '9 WALNUT WAY', '310 MAPLE DR', '88 PINE RD'])[1 + (g * 11 + 0) % 8],  -- patient_addr_line1
