  format('S%s', lpad((((1 + (g * 29) % 500 - 1) / 3) * 3 + 1)::text, 5, '0')),  -- subscriber_id
  (ARRAY['NGUYEN', 'GARCIA', 'SMITH', 'JOHNSON', 'KIM', 'PATEL', 'OKAFOR', 'MULLER'])[1 + (g * 3 + 0) % 8],  -- subscriber_last_name
  (ARRAY['ALEX', 'SAM', 'JORDAN', 'TAYLOR', 'CASEY', 'ROBIN', 'MORGAN', 'JAMIE'])[1 + (g * 7 + 2) % 8],  -- subscriber_first_name
  DATE '1955-01-01' + ((g * 83) % 14600),  -- subscriber_dob
  CASE g % 3 WHEN 0 THEN 'F' ELSE 'M' END,  -- subscriber_gender
  (ARRAY['100 MAIN ST', '42 OAK AVE', '7 ELM CT', '1600 BIRCH BLVD', '250 CEDAR LN', '9 WALNUT WAY', '310 MAPLE DR', '88 PINE RD'])[1 + (g * 11 + 0) % 8],  -- subscriber_addr_line1
  (ARRAY['SPRINGFIELD', 'RIVERSIDE', 'FRANKLIN', 'GREENVILLE', 'CLINTON', 'SALEM', 'MADISON', 'GEORGETOWN'])[1 + (g * 13 + 0) % 8],  -- subscriber_city
