  CASE WHEN g % 6 = 0 THEN (ARRAY['CO', 'PR', 'OA'])[1 + (g * 3 + 2) % 3] END,  -- cas_group_code_2
  CASE WHEN g % 6 = 0 THEN (ARRAY['1', '2', '3', '45', '96', '97'])[1 + (g * 5 + 2) % 6] END,  -- cas_reason_code_2
  CASE WHEN g % 6 = 0 THEN round((100 + (g * 19) % 20000)::numeric / 100, 2) END,  -- cas_amount_2
  CASE WHEN g % 9 = 0 THEN (ARRAY['CO', 'PR', 'OA'])[1 + (g * 3 + 3) % 3] END,  -- cas_group_code_3
  CASE WHEN g % 9 = 0 THEN (ARRAY['1', '2', '3', '45', '96', '97'])[1 + (g * 5 + 3) % 6] END,  -- cas_reason_code_3
  CASE WHEN g % 9 = 0 THEN round((100 + (g * 20) % 20000)::numeric / 100, 2) END,  -- cas_amount_3
  CASE WHEN g % 12 = 0 THEN (ARRAY['CO', 'PR', 'OA'])[1 + (g * 3 + 4) % 3] END,  -- cas_group_code_4
  CASE WHEN g % 12 = 0 THEN (ARRAY['1', '2', '3', '45', '96', '97'])[1 + (g * 5 + 4) % 6] END,  -- cas_reason_code_4
  CASE WHEN g % 12 = 0 THEN round((100 + (g * 21) % 20000)::numeric / 100, 2) END,  -- cas_amount_4
  CASE WHEN g % 15 = 0 THEN (ARRAY['CO', 'PR', 'OA'])[1 + (g * 3 + 5) % 3] END,  -- cas_group_code_5
  CASE WHEN g % 15 = 0 THEN (ARRAY['1', '2', '3', '45', '96', '97'])[1 + (g * 5 + 5) % 6] END,  -- cas_reason_code_5
  CASE WHEN g % 15 = 0 THEN round((100 + (g * 22) % 20000)::numeric / 100, 2) END,  -- cas_amount_5
  CASE WHEN g % 2 = 0 THEN lpad((190 + (g * 3) % 120)::text, 3, '0') END,  -- drg_code
  CASE WHEN g % 2 = 0 THEN round((0.5 + (g * 7) % 300 / 100.0)::numeric, 4) END,  -- drg_weight
  (ARRAY['fee_schedule', 'fee_schedule', 'drg', 'per_diem', 'percent_of_charge'])[1 + (g * 7 + 0) % 5],  -- pricing_method
  CASE WHEN g % 8 = 0 THEN 'O' ELSE 'I' END,  -- network_indicator
  62.00,  -- allowed_percent
  lpad(((g * 7) % 1000000000)::text, 9, '0'),  -- isa_interchange_control_number
  ((g * 11) % 900000 + 100000)::text,  -- gs_group_control_number
  lpad((g % 10000)::text, 4, '0'),  -- st_transaction_control_number
  30 + g % 40,  -- se_segment_count
  (ARRAY['SUB001', 'SUB002', 'SUB003'])[1 + (g * 3 + 0) % 3],  -- submitter_id
  (ARRAY['APEX BILLING SVC', 'BRIGHTPATH RCM', 'CLEARWATER BILLING'])[1 + (g * 3 + 0) % 3],  -- submitter_name
  'RCV001',  -- receiver_id
  'ACME HEALTH PLAN',  -- receiver_name
  (ARRAY['CH01', 'CH02'])[1 + (g * 1 + 0) % 2],  -- clearinghouse_id
  (ARRAY['RELAYNET', 'SWITCHPOINT'])[1 + (g * 1 + 0) % 2],  -- clearinghouse_name
  format('B%s', lpad(((g - 1) / 100)::text, 5, '0')),  -- clearinghouse_batch_id
  '005010X222A1',  -- edi_version_code
  '00',  -- transaction_set_purpose
  CASE WHEN g % 20 = 0 OR g % 41 = 0 THEN format('WC%s', lpad((g - 1)::text, 7, '0')) END,  -- original_claim_id
  CASE WHEN g % 20 = 0 OR g % 41 = 0 THEN (ARRAY['1', '2', '3'])[1 + (g * 3 + 0) % 3] END,  -- resubmission_condition_code
  CASE WHEN g % 6 = 0 THEN format('PA%s', lpad(((g * 19) % 1000000)::text, 6, '0')) END,  -- prior_auth_number
  CASE WHEN g % 9 = 0 THEN format('RF%s', lpad(((g * 23) % 1000000)::text, 6, '0')) END,  -- referral_number
  CASE WHEN g % 31 = 0 THEN format('ATT%s', lpad((g % 100000)::text, 5, '0')) END,  -- attachment_control_number
  CASE WHEN (g + 0) % 31 = 0 THEN 'Y' ELSE 'N' END,  -- attachment_flag
  CASE WHEN (g + 4) % 12 = 0 THEN 'Y' ELSE 'N' END,  -- emergency_indicator
  CASE WHEN (g + 9) % 50 = 0 THEN 'Y' ELSE 'N' END,  -- epsdt_flag
  CASE WHEN (g + 11) % 60 = 0 THEN 'Y' ELSE 'N' END,  -- family_planning_flag
  CASE WHEN (g + 2) % 15 = 0 THEN 'Y' ELSE 'N' END,  -- accident_related_flag
  CASE WHEN (g + 2) % 45 = 0 THEN 'Y' ELSE 'N' END,  -- auto_accident_flag
  CASE WHEN (g + 2) % 15 = 0 THEN (ARRAY['OH', 'TX', 'CA', 'NY', 'IL', 'GA', 'WA', 'PA'])[1 + (g * 7 + 0) % 8] END,  -- accident_state
  CASE WHEN (g + 2) % 15 = 0 THEN DATE '2025-01-01' + ((g * 11) % 540) - 3 END,  -- accident_date
  CASE WHEN (g + 8) % 75 = 0 THEN 'Y' ELSE 'N' END,  -- employment_related_flag
  CASE WHEN g % 30 = 0 THEN 'I' ELSE 'Y' END,  -- release_of_information_code
  CASE WHEN (g + 6) % 14 = 0 THEN 'Y' ELSE 'N' END,  -- assignment_of_benefits_flag
  CASE WHEN g % 22 = 0 THEN 'C' ELSE 'A' END,  -- provider_accept_assignment
  CASE WHEN g % 4 = 0 THEN 'S' ELSE 'P' END,  -- patient_signature_source
  CASE WHEN g % 27 = 0 THEN (ARRAY['1', '3', '7', '9'])[1 + (g * 3 + 0) % 4] END,  -- delay_reason_code
  CASE WHEN g % 17 = 0 THEN (ARRAY['SEE ATTACHED RECORDS', 'CORRECTED MEMBER ID', 'TIMELY FILING APPEAL'])[1 + (g * 3 + 0) % 3] END  -- claim_note_text
FROM generate_series(1, 2000) g;

ANALYZE claims.claims_837_wide;
